-- ---------------------------------------------------------------- Chronal Artificer (#reforge)
DELETE s FROM spawn2 s JOIN spawnentry e ON e.spawngroupID = s.spawngroupID WHERE e.npcID = 1200050;
DELETE g FROM spawngroup g JOIN spawnentry e ON e.spawngroupID = g.id WHERE e.npcID = 1200050;
DELETE FROM spawnentry WHERE npcID = 1200050;
DELETE FROM npc_types WHERE id = 1200050;
DROP TEMPORARY TABLE IF EXISTS sink_npc;
CREATE TEMPORARY TABLE sink_npc SELECT * FROM npc_types WHERE id = 1200010;
UPDATE sink_npc SET id = 1200050, name = 'Chronal_Artificer', lastname = 'Reforging', class = 1, merchant_id = 0, alt_currency_id = 0;
DROP TEMPORARY TABLE sink_npc;
SET @sg = (SELECT MAX(id) + 1 FROM spawngroup);
