INSERT INTO tributes (id, unknown, name, descr, isguild) VALUES (62, 5, 'Chronal Bulwark', 'Moments that never happened harden around you.<br>Works only inside a Greater Rift. Tiers stack: tier III also turns on I and II, so it works in rift tiers 1-300, giving the benefit of the rift''s band. Instead of a cost every 10 minutes, it takes 100 favor x the rift tier once per run, on entering the rift. The cost shown is for the top of the band.<br>Benefit -<br>I (rift tiers 1-100): 5 AC, 75 HP, 3 Heroic Stamina, 2 Heroic Magic Resist, 2 Heroic Fire Resist, 2 Heroic Cold Resist, 2 Heroic Disease Resist, 2 Heroic Poison Resist<br>II (rift tiers 101-200): 10 AC, 150 HP, 6 Heroic Stamina, 4 Heroic Magic Resist, 4 Heroic Fire Resist, 4 Heroic Cold Resist, 4 Heroic Disease Resist, 4 Heroic Poison Resist<br>III (rift tiers 201-300): 15 AC, 225 HP, 9 Heroic Stamina, 6 Heroic Magic Resist, 6 Heroic Fire Resist, 6 Heroic Cold Resist, 6 Heroic Disease Resist, 6 Heroic Poison Resist<br>IV (rift tiers 301-400): 20 AC, 300 HP, 12 Heroic Stamina, 8 Heroic Magic Resist, 8 Heroic Fire Resist, 8 Heroic Cold Resist, 8 Heroic Disease Resist, 8 Heroic Poison Resist<br>V (rift tiers 401-500): 25 AC, 375 HP, 15 Heroic Stamina, 10 Heroic Magic Resist, 10 Heroic Fire Resist, 10 Heroic Cold Resist, 10 Heroic Disease Resist, 10 Heroic Poison Resist', 0);
