INSERT INTO tributes (id, unknown, name, descr, isguild) VALUES (63, 5, 'Chronal Fortune', 'More of each Fracture''s shattered time clings to you as it closes.<br>Works only inside a Greater Rift. Tiers stack: tier III also turns on I and II, so it works in rift tiers 1-300, giving the benefit of the rift''s band. Instead of a cost every 10 minutes, it takes 100 favor x the rift tier once per run, on entering the rift. The cost shown is for the top of the band.<br>Benefit -<br>I (rift tiers 1-100): 5% more Chronal Shards from a clear<br>II (rift tiers 101-200): 10% more Chronal Shards from a clear<br>III (rift tiers 201-300): 15% more Chronal Shards from a clear<br>IV (rift tiers 301-400): 20% more Chronal Shards from a clear<br>V (rift tiers 401-500): 25% more Chronal Shards from a clear', 0);
